const roles={
  soldier:{name:'CHIẾN SĨ BỘ BINH',icon:'✦',short:'Tiến qua chiến hào, giữ vững đội hình.',call:'Chiến sĩ'},
  porter:{name:'DÂN CÔNG HỎA TUYẾN',icon:'◈',short:'Mang sức mạnh hậu phương ra tiền tuyến.',call:'Dân công'},
  courier:{name:'LIÊN LẠC VIÊN',icon:'✉',short:'Giữ mạch thông tin giữa các chốt.',call:'Liên lạc viên'}
};
const phases=[
  {name:'ĐỒN BẮN SÚNG MÁY',hazard:'machine',challenge:'HỎA LỰC SÚNG MÁY',q:'Theo bài giảng, Kế hoạch Nava muốn biến Điện Biên Phủ thành điều gì?',options:['Một “pháo đài bất khả xâm phạm” để quyết chiến','Một thương cảng quốc tế','Thủ đô mới của Đông Dương','Một căn cứ hải quân'],answer:0,fact:'Quân Pháp tập trung binh lực và tìm cách biến Điện Biên Phủ thành tập đoàn cứ điểm để quyết chiến.',source:'Buổi 13, slide 14'},
  {name:'LỐI QUA BÃI MÌN',hazard:'mine',challenge:'BÃI MÌN TRƯỚC CHIẾN HÀO',q:'Mục tiêu của cuộc tiến công chiến lược Đông Xuân 1953–1954 là gì?',options:['Rút toàn bộ lực lượng khỏi Tây Bắc','Giữ thế chủ động, buộc địch phân tán lực lượng','Chỉ tập trung phòng thủ Hà Nội','Chấm dứt mọi hoạt động quân sự'],answer:1,fact:'Bài giảng nhấn mạnh giữ vững thế chủ động, buộc đối phương phân tán lực lượng và bồi dưỡng lực lượng ta.',source:'Buổi 13, slide 15'},
  {name:'VƯỢT LÀN ĐẠN LẠC',hazard:'bullet',challenge:'ĐẠN LẠC QUA CHIẾN HÀO',q:'Ai được bài giảng nêu là Tư lệnh Chiến dịch Điện Biên Phủ?',options:['Nguyễn Văn Linh','Lê Duẩn','Đại tướng Võ Nguyên Giáp','Đỗ Mười'],answer:2,fact:'Đại tướng Võ Nguyên Giáp là Tư lệnh Chiến dịch Điện Biên Phủ.',source:'Buổi 13, slide 15'},
  {name:'VÙNG PHÁO KÍCH',hazard:'artillery',challenge:'PHÁO KÍCH GẦN HẦM CHỈ HUY',q:'Thắng lợi Điện Biên Phủ được giáo trình gắn với kết quả ngoại giao nào?',options:['Hiệp định Paris 1973','Cương lĩnh 1991','Hiệp định Genève 1954','Hiệp định Sơ bộ 1946'],answer:2,fact:'Bài giảng đặt chiến thắng Điện Biên Phủ cùng tiến trình đàm phán và Hiệp định Genève năm 1954.',source:'Buổi 13, slide 16–17'},
  {name:'NÓC HẦM CHỈ HUY',hazard:'bunker',challenge:'CHỐT CUỐI — TIẾN VỀ HẦM CHỈ HUY',q:'Chiến dịch Điện Biên Phủ toàn thắng vào ngày nào?',options:['2/9/1945','7/5/1954','21/7/1954','30/4/1975'],answer:1,fact:'Ngày 7/5/1954 là mốc toàn thắng của Chiến dịch Điện Biên Phủ. Lá cờ chiến thắng được cắm trên nóc hầm chỉ huy.',source:'Mốc chiến dịch; đối chiếu Buổi 13–14'}
];
const $=s=>document.querySelector(s);
const scene=$('#scene'),panel=$('#game-panel'),outcome=$('#outcome'),effects=$('#effects'),runner=$('#runner');
let role=null,phase=0,state='briefing',optionOrder=[],soundOn=false,audioCtx=null,pending=[];
const schedule=(fn,ms)=>{const t=setTimeout(fn,ms);pending.push(t);return t};
const clearPending=()=>{pending.forEach(clearTimeout);pending=[]};
function sound(freq=300,duration=.14,type='sine',volume=.08){if(!soundOn)return;try{audioCtx ||= new(window.AudioContext||window.webkitAudioContext)();const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type=type;osc.frequency.setValueAtTime(freq,audioCtx.currentTime);gain.gain.setValueAtTime(volume,audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);osc.connect(gain).connect(audioCtx.destination);osc.start();osc.stop(audioCtx.currentTime+duration)}catch{}}
function riff(win){[0,140,280,420].forEach((d,i)=>schedule(()=>sound((win?440:260)+(win?i*110:-i*40),.18,win?'triangle':'sawtooth',.07),d))}
function shuffle(a){const list=[...a];for(let i=list.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[list[i],list[j]]=[list[j],list[i]]}return list}
function updateHud(){const name=role?roles[role].name:'CHƯA CHỌN VAI';$('#role-label').textContent=name;$('#stage-label').textContent=state==='briefing'?'SẴN SÀNG XUẤT PHÁT':state==='victory'?'CHIẾN DỊCH TOÀN THẮNG':state==='fallen'?'NHIỆM VỤ KẾT THÚC':`CHỐT ${String(phase+1).padStart(2,'0')} / 05`;$('#runner-name').textContent=role?roles[role].call.toUpperCase():'CHIẾN SĨ';$('#threat-indicator').lastElementChild.textContent=state==='question'?phases[phase].challenge:state==='briefing'?'CHỜ LỆNH XUẤT PHÁT':state==='victory'?'CHIẾN THẮNG':'CHIẾN TRƯỜNG TẠM LẮNG';$('#field-progress').innerHTML=phases.map((p,i)=>`<span class="${i<phase||state==='victory'?'done':i===phase&&state!=='briefing'?'current':''}" title="Chốt ${i+1}: ${p.name}">${i<phase||state==='victory'?'✓':i+1}</span>`).join('')}
function renderBriefing(){state='briefing';phase=0;role=null;clearPending();outcome.hidden=true;outcome.className='outcome';scene.classList.remove('victory','danger','hit');runner.classList.remove('fallen','advancing');runner.style.left='8%';$('#flag-mast').style.opacity='';effects.replaceChildren();panel.innerHTML=`<span class="panel-kicker">HỒ SƠ NHẬP VAI / CHIẾN DỊCH 1954</span><h2 class="panel-title">CHỌN VAI CỦA BẠN</h2><p class="panel-copy">Bạn sẽ đi qua 5 chốt của chiến trường. Mỗi câu trả lời đúng giúp vượt qua một hiểm nguy. Trả lời sai, lượt chơi kết thúc và bạn có thể xuất phát lại.</p><div class="role-grid">${Object.entries(roles).map(([id,r])=>`<button class="role-card" data-role="${id}" aria-pressed="false"><span class="role-icon">${r.icon}</span><strong>${r.name}</strong><small>${r.short}</small></button>`).join('')}</div><button class="primary" data-action="start" disabled>NHẬN NHIỆM VỤ →</button>`;updateHud()}
function selectRole(id){role=id;document.querySelectorAll('.role-card').forEach(b=>{const selected=b.dataset.role===id;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected))});panel.querySelector('[data-action="start"]').disabled=false;updateHud();sound(540,.09,'triangle')}
function start(){if(!role)return;clearPending();state='question';phase=0;outcome.hidden=true;scene.classList.remove('victory','hit','danger');$('#flag-mast').style.opacity='';runner.classList.remove('fallen');runner.style.left='8%';effects.replaceChildren();renderQuestion();launchThreat();sound(360,.18,'triangle')}
function renderQuestion(){state='question';const p=phases[phase];optionOrder=shuffle(p.options.map((text,index)=>({text,correct:index===p.answer})));panel.innerHTML=`<div class="question-head"><span>CHỐT ${String(phase+1).padStart(2,'0')} / 05 — ${p.name}</span><span>CHỌN A, B, C HOẶC D</span></div><div class="question-text">${p.q}</div><div class="option-grid">${optionOrder.map((o,i)=>`<button class="option" data-answer="${o.correct?'yes':'no'}"><span>${'ABCD'[i]}.</span>${o.text}</button>`).join('')}</div>`;updateHud()}
function launchThreat(){const hazard=phases[phase].hazard;scene.classList.add('danger');$('#threat-indicator').classList.add('active');spawnTracers(hazard==='mine'?2:hazard==='bunker'?5:4);if(hazard==='mine'||hazard==='artillery')spawnImpact(hazard==='mine'?60:40,75);sound(hazard==='machine'?190:110,.19,'sawtooth',.055);schedule(()=>scene.classList.remove('danger'),1200)}
function spawnTracers(count){for(let i=0;i<count;i++){schedule(()=>{const el=document.createElement('i');el.className='tracer';el.style.left='108%';el.style.top=`${37+Math.random()*43}%`;effects.append(el);schedule(()=>el.remove(),800)},i*140)}}
function spawnImpact(x,y){const el=document.createElement('i');el.className='impact';el.style.left=`${x}%`;el.style.top=`${y}%`;effects.append(el);schedule(()=>el.remove(),900)}
function spawnSparks(x=75,y=50,count=18){for(let i=0;i<count;i++){const el=document.createElement('i');el.className='spark';el.style.left=`${x}%`;el.style.top=`${y}%`;el.style.setProperty('--dx',`${(Math.random()-.5)*220}px`);el.style.setProperty('--dy',`${(Math.random()-.5)*170}px`);effects.append(el);schedule(()=>el.remove(),1500)}}
function answer(button){if(state!=='question')return;state='resolving';const correct=button.dataset.answer==='yes';panel.querySelectorAll('.option').forEach(b=>{b.disabled=true;if(b.dataset.answer==='yes')b.classList.add('correct');else if(b===button)b.classList.add('wrong')});if(correct){sound(640,.15,'triangle');const nextX=Math.min(8+(phase+1)*16.5,79);runner.classList.add('advancing');runner.style.left=`${nextX}%`;spawnSparks(17+(phase*16),68,8);schedule(()=>{runner.classList.remove('advancing');state='feedback';const p=phases[phase];panel.insertAdjacentHTML('beforeend',`<div class="feedback-note"><strong>ĐÃ VƯỢT QUA ${p.name}!</strong><p>${p.fact}</p><small>Nguồn: giáo trình VNR202, ${p.source}</small></div><button class="primary" data-action="continue">${phase===phases.length-1?'CẮM CỜ CHIẾN THẮNG ⚑':'TIẾN ĐẾN CHỐT TIẾP THEO →'}</button>`);updateHud()},900)}else{scene.classList.add('hit','danger');spawnTracers(6);spawnImpact(22+phase*15,71);sound(95,.5,'sawtooth',.15);schedule(()=>{runner.classList.add('fallen');scene.classList.remove('hit');showFallen()},650)}}
function showFallen(){state='fallen';const p=phases[phase];outcome.hidden=false;outcome.className='outcome fallen';outcome.innerHTML=`<div class="outcome-inner"><span class="outcome-icon">✦</span><span class="panel-kicker">NHIỆM VỤ DỪNG Ở CHỐT ${phase+1} / 5</span><h2>BẠN ĐÃ HY SINH<br><em>THẬT ANH DŨNG</em></h2><p>${roles[role].call} đã dũng cảm tiến về phía trước. Ghi nhớ kiến thức, rồi trở lại chiến hào để hoàn thành nhiệm vụ.</p><div class="actions"><button class="primary" data-action="retry">THỬ LẠI TỪ ĐẦU ↻</button><button class="secondary" data-action="reselect">CHỌN VAI KHÁC</button></div><small class="source">Đáp án đúng: ${p.options[p.answer]}. ${p.fact} — ${p.source}</small></div>`;panel.innerHTML=`<span class="panel-kicker">HỒ SƠ CHƯA HOÀN THÀNH</span><h2 class="panel-title">ĐỪNG ĐỂ KIẾN THỨC DỪNG LẠI</h2><p class="panel-copy">Đọc lại lời giải trong khung chiến trường và thử thêm lần nữa.</p>`;updateHud();riff(false)}
function next(){if(state!=='feedback')return;if(phase===phases.length-1){showVictory();return}phase++;renderQuestion();launchThreat()}
function showVictory(){state='victory';scene.classList.add('victory');$('#flag-mast').style.opacity='1';spawnSparks(88,35,35);for(let i=0;i<60;i++){const el=document.createElement('i');el.className='confetti';el.style.left=`${Math.random()*100}%`;el.style.animationDelay=`${Math.random()*2}s`;el.style.animationDuration=`${2+Math.random()*2}s`;el.style.background=['#eac36c','#d9342b','#f4e1ad'][i%3];effects.append(el)}outcome.hidden=false;outcome.className='outcome victory';outcome.innerHTML=`<i class="firework one"></i><i class="firework two"></i><i class="firework three"></i><div class="outcome-inner"><span class="outcome-icon">★</span><span class="panel-kicker">07 / 05 / 1954 — CHIẾN DỊCH TOÀN THẮNG</span><h2>CHÚC MỪNG<br><em>BẠN ĐÃ CHIẾN THẮNG!</em></h2><p>Năm chốt kiến thức đã được vượt qua. Lá cờ đỏ sao vàng tung bay trên nóc hầm chỉ huy — dấu mốc của chiến thắng Điện Biên Phủ.</p><div class="actions"><button class="primary" data-action="retry">CHƠI LẠI ↻</button><a class="secondary" href="index.html#dien-bien">TRỞ VỀ HÀNH TRÌNH</a></div><small class="source">“Lừng lẫy năm châu, chấn động địa cầu” • Giáo trình VNR202, buổi 13–14</small></div>`;panel.innerHTML=`<span class="panel-kicker">HỒ SƠ CHIẾN DỊCH ĐÃ HOÀN THÀNH</span><h2 class="panel-title">LÁ CỜ ĐÃ ĐƯỢC DỰNG LÊN</h2><p class="panel-copy">Bạn đã trả lời đúng toàn bộ 5 câu hỏi về bối cảnh, chiến lược, chỉ huy và kết quả của chiến dịch.</p>`;try{localStorage.setItem('vnr202-dienbien-best','victory')}catch{}updateHud();riff(true);sound(660,.5,'triangle',.09)}
document.addEventListener('click',e=>{const r=e.target.closest('[data-role]');if(r&&state==='briefing'){selectRole(r.dataset.role);return}const a=e.target.closest('[data-action]');if(a){if(a.dataset.action==='start')start();if(a.dataset.action==='continue')next();if(a.dataset.action==='retry')start();if(a.dataset.action==='reselect')renderBriefing();return}const o=e.target.closest('[data-answer]');if(o)answer(o)});
document.addEventListener('keydown',e=>{if(state!=='question'||!['1','2','3','4'].includes(e.key))return;const buttons=[...panel.querySelectorAll('.option')];buttons[Number(e.key)-1]?.click()});
$('#sound-toggle').addEventListener('click',e=>{soundOn=!soundOn;e.currentTarget.setAttribute('aria-pressed',String(soundOn));e.currentTarget.setAttribute('aria-label',soundOn?'Tắt âm thanh hiệu ứng':'Bật âm thanh hiệu ứng');e.currentTarget.textContent=soundOn?'♫ ÂM THANH: BẬT':'♪ ÂM THANH: TẮT';if(soundOn)sound(660,.14,'triangle')});
renderBriefing();
